const novCmp=(a,b)=>{const x=String(a).split(".").map(Number),y=String(b).split(".").map(Number);for(let i=0;i<Math.max(x.length,y.length);i++){const d=(x[i]||0)-(y[i]||0);if(d)return d}return 0};
const novKey=()=>"g360_visto_"+String(EU&&EU.email||"").toLowerCase();
let NOV_VISTO=null;
function novVisto(){if(NOV_VISTO)return NOV_VISTO;try{return localStorage.getItem(novKey())||""}catch(e){return ""}}
function novMarcar(){NOV_VISTO=VERSAO;try{localStorage.setItem(novKey(),VERSAO)}catch(e){}try{prefsAgendar()}catch(e){}}
function novAbrir(desde,todas){const L=(todas?NOVIDADES.concat(NOV_HIST):NOVIDADES).filter(n=>todas?true:desde?novCmp(n.v,desde)>0:n.v===NOVIDADES[0].v);if(!L.length)return false;
  $("#novSub").textContent=todas?"Histórico das versões":desde?`Desde a sua última visita (versão ${desde}) · ${L.length} atualizaç${L.length===1?"ão":"ões"}`:`Versão ${VERSAO}`;
  $("#novL").innerHTML=L.map((n,k)=>`<div class="nov-v"><div class="nov-vh"><b>${/^\d/.test(n.v)?"Versão "+esc(n.v):esc(n.v)}</b><span>${esc(n.d)}</span>${k===0&&n.v===VERSAO?"<i>atual</i>":""}</div><ul>${n.i.map(t=>`<li>${esc(t)}</li>`).join("")}</ul></div>`).join("");
  $("#novBg").hidden=false;setTimeout(()=>{try{$("#novOk").focus()}catch(e){}},50);return true}
function novFechar(){$("#novBg").hidden=true;novMarcar()}
function novVer(){try{if(!EU||!EU.email)return;const v=novVisto();if(v&&novCmp(VERSAO,v)<=0)return;if(!novAbrir(v,false))novMarcar()}catch(e){}}
$("#novOk").onclick=novFechar;
$("#novBg").addEventListener("click",e=>{if(e.target.id==="novBg")novFechar()});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#novBg").hidden)novFechar()});
document.querySelectorAll(".top .brand .ver, nav.side .sbrand .ver").forEach(el=>{el.title="Ver as novidades";el.addEventListener("click",e=>{e.stopPropagation();novAbrir("",true)})});

/* 0.9.84: Definições › Histórico de versões (NOVIDADES + NOV_HIST), por fases da app */
function renderHist(){const el=$("#histL");if(!el)return;const q=norm($("#histQ").value||"");
  const A=NOVIDADES.map(n=>Object.assign({fase:"EPISJ 360"},n)).concat(NOV_HIST.map(n=>Object.assign({fase:/^BoxDoc|^EPISJ Box/.test(n.v)?"BoxDoc":/^BoxCheck/.test(n.v)?"BoxCheck":/^GUIDE/.test(n.v)?"GUIDE":"EPISJ 360"},n)));
  const F=A.filter(n=>!q||norm(n.v+" "+n.i.join(" ")).includes(q));
  const fases=[["EPISJ 360","a app da escola, com todos os módulos"],["GUIDE","a BoxCheck passa a módulo de uma app maior"],["BoxCheck","controlo das entregas na Box"],["BoxDoc","as primeiras versões"]];
  $("#histN").textContent=`${F.length} versõe${F.length===1?"":"s"}${q?" encontradas":""}`;
  el.innerHTML=fases.map(([f,d],k)=>{const G=F.filter(n=>n.fase===f);if(!G.length)return"";
    return `<details${k===0||q?" open":""}><summary>${esc(f)} <small>${esc(d)} · ${G.length} versõe${G.length===1?"":"s"}</small></summary>${G.map(n=>`<div class="hv"><b>${/^\d/.test(n.v)?"Versão "+esc(n.v):esc(n.v)}<span>${esc(n.d)}</span></b><ul>${n.i.map(t=>`<li>${esc(t)}</li>`).join("")}</ul></div>`).join("")}</details>`}).join("")||`<p class="hint">Nada encontrado.</p>`}
(()=>{const q=$("#histQ");if(q)q.addEventListener("input",debounce(()=>renderHist(),120));renderHist()})();
/* 0.9.50: a escolha dos widgets e a disposição dos quadros ficam guardadas na conta (Supabase, tabela g360_prefs, só a própria pessoa):
   são as mesmas em todos os computadores e no iPad, e mudam em tempo real nos outros aparelhos abertos */
var PREFS={t:+(localStorage.getItem("guide_prefs_t")||0),h:null,rt:null,ok:false};
/* 0.9.148: preferências de ecrã que antes ficavam no computador (tamanho da letra, vistas, filtros, marcas da cópia do OneDrive,
   aspeto do Horários360 e do Social360…) passam a viajar com a conta, em g360_prefs.dados.ls */
const PREF_LS=/^(boxcheck_letra|rc_vista|pc_t|cal_t|cal_ano|dsd_sel|guide_mh_turma|guide_wg_cal|guide_wg_crono|pw_min|box_fp_todos|g360_txf|g360_rep_off|g360_dev|boxcheck_tl|boxcheck_rps|g360_od_dia|g360_od_t|g360_od_falta|g360_exp_od|g360_priv_on|g360_wg_aniv|g360_wg_aniv2|h360_modo|ph-tema|ph-zoom|s360:ui:v1|s360:seen:.*)$/;
let PREF_LS_APLICAR=false;
function prefsLS(){const o={};try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&PREF_LS.test(k)){const v=localStorage.getItem(k);if(v!=null&&v.length<20000)o[k]=v}}}catch(e){}return o}
function prefsLSAplicar(o){if(!o||typeof o!=="object")return;PREF_LS_APLICAR=true;
  try{for(const k in o)if(PREF_LS.test(k)&&typeof o[k]==="string"&&localStorage.getItem(k)!==o[k])localStorage.setItem(k,o[k])}catch(e){}finally{PREF_LS_APLICAR=false}
  try{const v=+o.boxcheck_letra;if(FSZ.includes(v)&&v!==fsz){fsz=v;aplicarLetra()}}catch(e){}}
// cada alteração a uma destas chaves (também vinda do Horários360 ou do Social360) vai para a conta; os pontos de restauro vão para a base de dados
try{window.__g360Mem.ls.aoMudar=k=>{if(PREF_LS_APLICAR)return;if(PREF_LS.test(k))prefsAgendar();else if(k===RPKEY&&!RP_APLICAR)rpAgendar()}}catch(e){}
/* 0.9.148: pontos de restauro na base de dados (peça «RP»), só da Direção: já não ficam no computador */
let RP_APLICAR=false;
function rpAgendar(){try{if(!nuvSB())return;nuvFila("RP",()=>{try{nuvemPut("RP",{t:Date.now(),l:rpList()},Date.now())}catch(e){}},4000)}catch(e){}}
async function rpTrazer(){if(RO||!nuvSB())return;const idx=(await (await nuvem("GET","")).json()).itens||{};if(!idx.RP)return;const r=await nuvemGet("RP");if(!r||!Array.isArray(r.l))return;
  const m=new Map();rpList().concat(r.l).forEach(p=>{if(p&&p.t)m.set(p.t+"|"+p.label,p)});const L=[...m.values()].sort((a,b)=>b.t-a.t).slice(0,10);
  RP_APLICAR=true;try{localStorage.setItem(RPKEY,JSON.stringify(L))}catch(e){}finally{RP_APLICAR=false}try{renderRP()}catch(e){}}
function prefsDados(){let lay={};try{lay=JSON.parse(localStorage.getItem(LAYKEY)||"{}")||{}}catch(e){}return{wg1:WG_SEL,wg2:WG_SEL2,layout:lay,modord:MODORD||null,tema:temaAtual(),priv:(EU&&privDe())||null,visto:(typeof novVisto==="function"&&novVisto())||null,ls:prefsLS()}}
function prefsAgendar(){if(typeof PREFS==="undefined"||!PREFS)return;if(!PREFS.ok)PREFS.sujo=true;PREFS.t=Date.now();try{localStorage.setItem("guide_prefs_t",String(PREFS.t))}catch(e){}clearTimeout(PREFS.h);nuvFila("PREFS_h",prefsEnviar,1200)}
async function prefsEnviar(){if(!PREFS.ok)return;try{const em=String(EU&&EU.email||"").toLowerCase();if(!em||!SBSES)return;const sb=await sbCliente();
  const {error}=await sb.from("g360_prefs").upsert({email:em,dados:prefsDados(),t:PREFS.t||Date.now(),por:SBSID},{onConflict:"email"});if(error)console.warn("preferências",error.message||error)}catch(e){}}
function layAplicar(){document.querySelectorAll("main>section").forEach(sec=>{const L=LAYOUT[sec.id];if(!L)return;
  for(const ck in L){const cont=ck==="a"||ck==="b"?sec.querySelector(`:scope>.cols>.col[data-col="${ck}"]`):sec.querySelector(`[data-cont="${CSS.escape(ck)}"]`);if(!cont)continue;
    for(const bk of L[ck]){const b=sec.querySelector(`[data-blk="${CSS.escape(bk)}"]`);if(b&&!b.contains(cont))cont.appendChild(b)}}})}
function prefsAplicar(d,t){if(!d||typeof d!=="object")return;
  try{prefsLSAplicar(d.ls)}catch(e){}
  if(Array.isArray(d.wg1))WG_SEL=d.wg1.filter(x=>typeof x==="string");if(Array.isArray(d.wg2))WG_SEL2=d.wg2.filter(x=>typeof x==="string");try{if(!(d.wg1||[]).includes("aniv")&&!(d.wg2||[]).includes("aniv")&&!localStorage.getItem("g360_wg_aniv2")){localStorage.setItem("g360_wg_aniv2","1");WG_SEL.unshift("aniv");setTimeout(()=>{try{wgGuardar()}catch(e){}},0)}}catch(e){}
  try{localStorage.setItem(WG_KEY,JSON.stringify(WG_SEL));localStorage.setItem(WG_KEY+"2",JSON.stringify(WG_SEL2))}catch(e){}
  if(d.layout&&typeof d.layout==="object"&&JSON.stringify(d.layout)!==JSON.stringify(LAYOUT)){LAYOUT=d.layout;try{localStorage.setItem(LAYKEY,JSON.stringify(LAYOUT))}catch(e){}try{layAplicar()}catch(e){}}
  if(d.visto&&typeof d.visto==="string"&&(!novVisto()||novCmp(d.visto,novVisto())>0)){NOV_VISTO=d.visto;try{localStorage.setItem(novKey(),d.visto)}catch(e){}}
  if(Array.isArray(d.modord)&&JSON.stringify(d.modord)!==JSON.stringify(MODORD))try{modOrdGuardar(d.modord.filter(x=>typeof x==="string"),false)}catch(e){}
  if(typeof d.tema==="string"&&d.tema!==temaAtual())try{temaAplicar(d.tema,false)}catch(e){}
  if(d.priv)try{privDaConta(d.priv)}catch(e){}
  PREFS.t=t||Date.now();try{localStorage.setItem("guide_prefs_t",String(PREFS.t))}catch(e){}
  if(curTab==="esc")renderWidgets()}
async function prefsTrazer(){try{const em=String(EU&&EU.email||"").toLowerCase();if(!em||!SBSES)return;const sb=await sbCliente();
  const {data,error}=await sb.from("g360_prefs").select("dados,t").eq("email",em).maybeSingle();if(error){console.warn("preferências",error.message||error);return}PREFS.ok=true;
  /* 0.9.154: na primeira leitura desta página a conta manda sempre (o navegador já não guarda nada entre visitas, por isso o que
     a página mudou enquanto arrancava — valores por omissão, marcas — não pode passar por cima do tema e dos widgets da conta) */
  const prim=!PREFS.lido;PREFS.lido=true;
  if(prim&&!(data&&data.dados&&Array.isArray(data.dados.wg1)))try{wgPadraoDoPerfil()}catch(e){} // 0.9.184: Dashboard do perfil a quem ainda não escolheu widgets
  if(data&&(prim||(+data.t||0)>PREFS.t)){prefsAplicar(data.dados,+data.t||Date.now());if(prim&&PREFS.sujo){PREFS.sujo=false;PREFS.t=Date.now();prefsEnviar()}}
  else if(!data||PREFS.t>(+data.t||0)){if(!PREFS.t)PREFS.t=Date.now();prefsEnviar()}
  if(!PREFS.rt&&sb.channel)PREFS.rt=sb.channel("g360-prefs-"+em).on("postgres_changes",{event:"*",schema:"public",table:"g360_prefs",filter:"email=eq."+em},p=>{const r=p.new||{};if(r.por===SBSID)return;if((+r.t||0)>PREFS.t)prefsAplicar(r.dados,+r.t)}).subscribe()}catch(e){}}



/* importa da análise do BoxCheck as turmas no formato "A04 - Mecatrónica Automóvel (25/28)" e cria os cursos */
function escImportarBox(){let T=[];try{T=turmasSNQ()}catch(x){}
  if(!T.length){toast("Ainda não há turmas na análise da Box — faça primeiro a análise em Box360 › Gestão Documental");return}
  ponto("Antes de importar as turmas da Box");const e=escData();let nc=0,nt=0,nu=0;
  for(const s of T){const cod=((s.match(/^\s*([a-z]?\d{1,4}[a-z]?)\b/i)||[])[1]||s).toUpperCase(),cn=cursoDe(s)||"(sem curso)";
    const m=s.match(/\(\s*(\d{2,4})\s*[-\/]\s*(\d{2,4})\s*\)/);let ai=null,af=null;if(m){ai=+m[1];af=+m[2];if(ai<100)ai+=2000;if(af<100)af+=2000}
    let c=e.cursos.find(x=>norm(x.nome)===norm(cn));if(!c){c={id:uid(),nome:cn,sigla:"",tipo:"Profissional",qual:null,itens:[]};e.cursos.push(c);nc++}
    const r=(cfg.snq||{})[norm(s)];if(r&&r.qual&&!c.qual){c.qual=Object.assign({},r.qual);c.itens=(r.itens||[]).slice();c.cands=(r.cands||[]).slice()}
    let t=e.turmas.find(x=>norm(x.nome||"")===norm(s))||e.turmas.find(x=>norm(x.cod)===norm(cod)&&(x.anoIni||null)===ai);
    if(t){t.nome=s;if(!cursoById(t.cursoId))t.cursoId=c.id;if(ai&&!t.anoIni){t.anoIni=ai;t.anoFim=af}nu++}
    else{e.turmas.push({id:uid(),cod,nome:s,cursoId:c.id,anoIni:ai,anoFim:af,dt:""});nt++}}
  e.cursos.sort((a,b)=>COLL_PT.compare(a.nome,b.nome));save();escRender();esRecarregar();
  toast(`Da Box: ${nt} turma(s) nova(s), ${nu} atualizada(s), ${nc} curso(s) novo(s)`)}

